def count_iqr_outliers(s):
    q1, q3 = s.quantile([0.25, 0.75])
    iqr = q3 - q1
    lower, upper = q1 - 1.5 * iqr, q3 + 1.5 * iqr  # 1.5 * IQR은 이상치 판단에 관례적으로 쓰이는 배수
    return ((s < lower) | (s > upper)).sum()

